def calculate_pi_leibniz(iterations):
    pi_approximation = 0.0
    for i in range(iterations):
        # Leibniz formula component
        pi_approximation += ((-1)**i) / (2*i + 1)
    return 4 * pi_approximation

if __name__ == "__main__":
    iterations = 1000
    pi_value = calculate_pi_leibniz(iterations)
    print(f"Approximation of Pi after {iterations} iterations: {pi_value}")
